module.exports = /*#__PURE__*/JSON.parse('{"title":"How to Pay Gas Fees With Any Token From Any Chain?","description":"Universal Transactions now support paying gas fees with ANY token on your native chain — one atomic call for funds, logic, and gas.","frontMatter":{"slug":"pay-gas-fees-with-any-token-from-any-chain","title":"How to Pay Gas Fees With Any Token From Any Chain?","authors":["push"],"image":"./cover-image.webp","description":"Universal Transactions now support paying gas fees with ANY token on your native chain — one atomic call for funds, logic, and gas.","text":"Universal Transactions just got a huge upgrade. You can now pay gas fees with ANY token on your native chain.","tags":["Maker Monday"]},"content":{"id":"pay-gas-fees-with-any-token-from-any-chain","metadata":{"permalink":"/push-chain-website/pr-preview/pr-1239/blog/pay-gas-fees-with-any-token-from-any-chain","source":"@site/blog/2026-03-02-pay-gas-fees-with-any-token-from-any-chain/index.md","title":"How to Pay Gas Fees With Any Token From Any Chain?","description":"Universal Transactions now support paying gas fees with ANY token on your native chain — one atomic call for funds, logic, and gas.","date":"2026-03-02T00:00:00.000Z","tags":[{"inline":true,"label":"Maker Monday","permalink":"/push-chain-website/pr-preview/pr-1239/blog/tags/maker-monday"}],"readingTime":0.93,"hasTruncateMarker":true,"authors":[{"name":"Push Chain","url":"https://x.com/PushChain","page":{"permalink":"/push-chain-website/pr-preview/pr-1239/blog/authors/push"},"imageURL":"/push-chain-website/pr-preview/pr-1239/assets/blog/authors/authorpush.png","key":"push"}],"frontMatter":{"slug":"pay-gas-fees-with-any-token-from-any-chain","title":"How to Pay Gas Fees With Any Token From Any Chain?","authors":["push"],"image":"./cover-image.webp","description":"Universal Transactions now support paying gas fees with ANY token on your native chain — one atomic call for funds, logic, and gas.","text":"Universal Transactions just got a huge upgrade. You can now pay gas fees with ANY token on your native chain.","tags":["Maker Monday"]},"unlisted":false,"prevItem":{"title":"What is the liquidity wedge trap? How to avoid it?","permalink":"/push-chain-website/pr-preview/pr-1239/blog/what-is-the-liquidity-wedge-trap"},"nextItem":{"title":"Understanding Push Chain’s Validator Stack","permalink":"/push-chain-website/pr-preview/pr-1239/blog/understanding-push-chain-validator-stack"}},"content":"![Cover Image of How to Pay Gas Fees With Any Token From Any Chain](./cover-image.webp)\\n\\n<!--truncate-->\\n\\nUniversal Transactions just got a huge upgrade ⚡️\\n\\nYou can now pay gas fees with ANY token on your native chain.\\n\\nThis means in one transaction, you can:\\n→ Send funds\\n→ Execute logic\\n→ Choose how to pay gas\\n\\nAll in one shot! \\n\\n\\n![payGasWith overview diagram](./image1.webp)\\n\\n## What makes this upgrade BIG?\\n\\nUniversal transactions can originate from ANY chain (EVM & non-EVM).\\nNormally, users must hold the native gas token of that origin chain.\\n\\nWith `payGasWith()` upgrade, the fee path becomes universal too.\\n\\nThis means:\\n- Devs don\'t have to rely on users to keep native gas.\\n- Users don\'t necessarily have to know how their chain\'s fee system works.\\n\\n## Behind the scenes\\n\\nPush Chain:\\n→ Takes the token you specify (USDT / USDC / anything)\\n→ Performs the necessary swap\\n→ Secures the gas\\n→ Executes + settles the universal txn\\n\\nAll packaged inside one atomic call, fully abstracting native gas.\\n\\n## Fine-grained controls\\n\\n- `slippageBps`: max allowed slippage on the ERC-20 → gas swap (100 = 1%).\\n- `minAmountOut`: the minimum acceptable output (in wei). If the swap can\'t meet this, the transaction reverts.\\n\\nPerfect for guaranteeing predictable fee execution.\\n\\n## Example\\n\\nA universal prediction market with users from Base, Ethereum, and BNBChain\\ncan all interact with the same liquidity pool.\\n\\n✅ Base users → pay fees in Base USDT\\n✅ ETH users → pay in DAI\\n✅ BNB users → pay in BUSD\\n\\nor through their native gas tokens. All supported in one pipeline.\\n\\n## Universal Transactions keep getting stronger.\\n\\nGas abstraction + universal fee payment unlocks a truly chain-agnostic experience.\\n\\n**Dive Deeper:**\\n- [SDK v3.0.8](https://npmjs.com/package/@pushchain/core?activeTab=readme)\\n- [Docs](https://push.org/docs/chain/build/send-universal-transaction/)"},"twitterId":""}');

